-- Application entry: GameSense modules are loaded by the recovered application.
local function initialize_application(...)
    local ffi_module = application_environment.require("ffi")
    local application = functions.create_application(
        nil, nil, nil, ffi_module, nil)
    return application({})
end
local arguments, argument_count = {...}, select("#", ...)
local function start()
    local count,result=pack_returns(initialize_application(unpack(arguments,1,argument_count)))
    check_startup_clock(true)
    return unpack(result,1,count)
end
